-- Empty experimental execution storage. No consent or provider request is created by deployment.
create table public.analysis_luna_native48_plans(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),set_id uuid not null,seal_id uuid not null,version text not null check(version='luna-native-balanced48-run-v1'),manifest jsonb not null,manifest_sha256 text not null check(manifest_sha256~'^[a-f0-9]{64}$'),created_by uuid references auth.users(id),actor_kind text not null check(actor_kind in('app_user','codex_admin')),created_at timestamptz not null default now(),
 foreign key(set_id,organization_id) references public.analysis_luna_balanced_sets(id,organization_id),foreign key(seal_id,organization_id) references public.analysis_luna_balanced_reference_seals(id,organization_id),unique(set_id,seal_id),unique(id,organization_id),check((actor_kind='app_user' and created_by is not null) or (actor_kind='codex_admin' and created_by is null))
);
create table public.analysis_luna_native48_runs(
 id uuid primary key default gen_random_uuid(),plan_id uuid not null unique,organization_id uuid not null,status text not null default 'queued' check(status in('queued','running','completed','failed','billing_uncertain')),started_at timestamptz not null default now(),completed_at timestamptz,
 consent_source text not null check(consent_source='user_directive_codex_delegation'),operator_identity jsonb not null,authorization_commit_sha text not null check(authorization_commit_sha='1b36499e81197d4ac0edc8cb9b7e6afa877214af'),authorization_spec_sha256 text not null check(authorization_spec_sha256='a2c5ca649169884194cacbdc345b9faa70f82c4deb8d73a8e8e7ed2729f48386'),authorization_record jsonb not null,authorization_sha256 text not null,authorization_recorded_by_role text not null check(authorization_recorded_by_role='service_role'),
 manifest_sha256 text not null,estimated_cost_usd numeric not null check(estimated_cost_usd>=0),max_calls int not null default 48 check(max_calls=48),automatic_retry boolean not null default false check(not automatic_retry),result jsonb,result_sha256 text,foreign key(plan_id,organization_id) references public.analysis_luna_native48_plans(id,organization_id),unique(id,organization_id)
);
create table public.analysis_luna_native48_tasks(
 id uuid primary key default gen_random_uuid(),run_id uuid not null,organization_id uuid not null,position int not null check(position between 1 and 48),review_id uuid not null references public.reviews(id),theme_key text not null,polarity text not null check(polarity in('positive','negative')),requested_model text not null default 'gpt-6-luna' check(requested_model='gpt-6-luna'),
 payload jsonb not null,request_sha256 text not null,source_text_sha256 text not null,status text not null default 'queued' check(status in('queued','dispatched','completed','failed','billing_uncertain','cancelled')),request_count int not null default 0 check(request_count in(0,1)),worker_id uuid,dispatched_at timestamptz,completed_at timestamptz,response jsonb,response_sha256 text,parsed jsonb,served_model text,answer_type text,response_id text,provider_request_id text,input_tokens bigint check(input_tokens>=0),output_tokens bigint check(output_tokens>=0),usage_details jsonb,cost_usd numeric check(cost_usd>=0),duration_ms bigint check(duration_ms>=0),error_code text,
 foreign key(run_id,organization_id) references public.analysis_luna_native48_runs(id,organization_id),unique(run_id,position),unique(run_id,review_id),check((status in('queued','cancelled') and request_count=0 and worker_id is null) or (status not in('queued','cancelled') and request_count=1 and worker_id is not null))
);
create table public.analysis_luna_native48_events(id uuid primary key default gen_random_uuid(),run_id uuid not null,organization_id uuid not null,event text not null,body jsonb not null default '{}',created_at timestamptz not null default now(),foreign key(run_id,organization_id) references public.analysis_luna_native48_runs(id,organization_id));
create table public.analysis_luna_native48_results(id uuid primary key default gen_random_uuid(),run_id uuid not null unique,organization_id uuid not null,body jsonb not null,result_sha256 text not null check(result_sha256~'^[a-f0-9]{64}$'),created_at timestamptz not null default now(),foreign key(run_id,organization_id) references public.analysis_luna_native48_runs(id,organization_id));
do $$declare tn text;begin foreach tn in array array['analysis_luna_native48_plans','analysis_luna_native48_runs','analysis_luna_native48_tasks','analysis_luna_native48_events','analysis_luna_native48_results'] loop
 execute format('alter table public.%I enable row level security',tn);execute format('revoke all on public.%I from anon,authenticated',tn);execute format('grant select on public.%I to authenticated',tn);execute format('grant all on public.%I to service_role',tn);
 execute format('create policy native48_org_read on public.%I for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=%I.organization_id and m.user_id=(select auth.uid()) and m.role in(''owner'',''admin'',''manager'')))',tn,tn);execute format('create index %I on public.%I(organization_id)',tn||'_org',tn);
end loop;end $$;
create index native48_plan_seal on public.analysis_luna_native48_plans(seal_id,organization_id);
create index native48_plan_actor on public.analysis_luna_native48_plans(created_by);
create index native48_task_queue on public.analysis_luna_native48_tasks(status,dispatched_at);
create index native48_task_review on public.analysis_luna_native48_tasks(review_id);
create index native48_event_run on public.analysis_luna_native48_events(run_id);
create trigger native48_plan_immutable before update or delete on public.analysis_luna_native48_plans for each row execute function public.pilot_evidence_immutable();
create trigger native48_event_immutable before update or delete on public.analysis_luna_native48_events for each row execute function public.pilot_evidence_immutable();
create trigger native48_result_immutable before update or delete on public.analysis_luna_native48_results for each row execute function public.pilot_evidence_immutable();
create function public.native48_source_check() returns jsonb language plpgsql security invoker set search_path='' as $$
declare s public.analysis_luna_balanced_sets;ref public.analysis_luna_balanced_reference_seals;c public.analysis_luna_balanced_cases;it jsonb;begin
 select * into s from public.analysis_luna_balanced_sets where id='a125ba0e-e4b0-49ca-83c8-1e52a27bd2be';select * into ref from public.analysis_luna_balanced_reference_seals where id='24883941-e3bc-4759-9af6-d21bd62413f9';
 if s.id is null or ref.id is null or s.organization_id<>'93228bbb-6397-41e3-b8be-21ee7060eda7' or ref.set_id<>s.id or ref.organization_id<>s.organization_id or s.manifest_sha256<>'5f0aeb92cf1d27890d447cd4ed9c6ab2f297773ad9b736912db44593c998caca' or ref.reference_sha256<>'ba06732a224c7f34b68208551abcc88d5d6c42b9713c32663d44df3e37df7781' or ref.dataset_sha256<>s.manifest_sha256 or s.manifest_sha256<>encode(extensions.digest(public.jev_economy_canonical(s.manifest),'sha256'),'hex') or ref.reference_sha256<>encode(extensions.digest(public.jev_economy_canonical(ref.body),'sha256'),'hex') then raise exception 'NATIVE48_SEAL_CHANGED';end if;
 if jsonb_array_length(s.manifest->'items')<>48 or jsonb_array_length(ref.body->'items')<>48 or (select count(*) from public.analysis_luna_balanced_cases where set_id=s.id)<>48 or (select count(*) from public.analysis_luna_balanced_references where set_id=s.id and seal_id=ref.id)<>48 or (select count(distinct establishment_id) from public.analysis_luna_balanced_cases where set_id=s.id)<>12 then raise exception 'NATIVE48_COUNT_CHANGED';end if;
 for c in select * from public.analysis_luna_balanced_cases where set_id=s.id loop
  select value into it from jsonb_array_elements(s.manifest->'items') where value->>'review_id'=c.review_id::text;
  if it is null or c.organization_id<>s.organization_id or it->>'position' is distinct from c.position::text or it->>'establishment_id' is distinct from c.establishment_id::text or it->>'rating' is distinct from c.rating::text or it->>'original_language' is distinct from c.original_language or it->>'original_text_sha256' is distinct from c.original_text_sha256 or it->>'theme_key' is distinct from c.theme_key or it->>'proposed_polarity' is distinct from c.proposed_polarity or it->>'axis' is distinct from c.axis or it->>'candidate_basis' is distinct from c.candidate_source or c.original_text_sha256<>encode(extensions.digest(convert_to(c.original_text,'UTF8'),'sha256'),'hex') or not exists(select 1 from public.reviews q join public.establishments e on e.id=q.establishment_id where q.id=c.review_id and q.organization_id=s.organization_id and e.organization_id=s.organization_id and q.establishment_id=c.establishment_id and q.original_text=c.original_text) then raise exception 'NATIVE48_LIVE_SOURCE_CHANGED';end if;
 end loop;
 for it in select value from jsonb_array_elements(ref.body->'items') loop
  if not exists(select 1 from public.analysis_luna_balanced_references q where q.set_id=s.id and q.seal_id=ref.id and q.organization_id=s.organization_id and q.review_id=(it->>'review_id')::uuid and q.theme_key=it->>'theme_key' and q.original_text_sha256=it->>'original_text_sha256' and q.choice=it->>'choice' and q.justification=it->>'justification') then raise exception 'NATIVE48_REFERENCE_CHANGED';end if;
 end loop;
 if not exists(select 1 from public.organization_members where organization_id=s.organization_id and user_id=s.created_by and role in('owner','admin','manager')) then raise exception 'FORBIDDEN';end if;
 return jsonb_build_object('set',to_jsonb(s),'seal',to_jsonb(ref),'cases',(select jsonb_agg(to_jsonb(q) order by position) from public.analysis_luna_balanced_cases q where set_id=s.id),'references',(select jsonb_agg(to_jsonb(q) order by review_id) from public.analysis_luna_balanced_references q where set_id=s.id and seal_id=ref.id),'restaurants',(select jsonb_agg(jsonb_build_object('id',e.id,'name',e.name,'organization_id',e.organization_id)) from public.establishments e where e.id in(select establishment_id from public.analysis_luna_balanced_cases where set_id=s.id)),'live_reviews',(select jsonb_agg(jsonb_build_object('id',q.id,'organization_id',q.organization_id,'establishment_id',q.establishment_id,'original_text',q.original_text)) from public.reviews q where id in(select review_id from public.analysis_luna_balanced_cases where set_id=s.id)));
end $$;
create function public.native48_state_guard() returns trigger language plpgsql security invoker set search_path='' as $$begin
 if tg_op='DELETE' then raise exception 'NATIVE48_IMMUTABLE';end if;
 if tg_table_name='analysis_luna_native48_runs' then
  if old.status in('completed','failed','billing_uncertain') or (to_jsonb(new)-array['status','result','result_sha256','completed_at']) is distinct from (to_jsonb(old)-array['status','result','result_sha256','completed_at']) or not(old.status='queued' and new.status='running' or old.status='running' and new.status in('running','completed','failed','billing_uncertain')) then raise exception 'NATIVE48_RUN_TRANSITION';end if;
 else
  if (to_jsonb(new)-array['status','request_count','worker_id','dispatched_at','completed_at','response','response_sha256','parsed','served_model','answer_type','response_id','provider_request_id','input_tokens','output_tokens','usage_details','cost_usd','duration_ms','error_code']) is distinct from (to_jsonb(old)-array['status','request_count','worker_id','dispatched_at','completed_at','response','response_sha256','parsed','served_model','answer_type','response_id','provider_request_id','input_tokens','output_tokens','usage_details','cost_usd','duration_ms','error_code']) or not(old.status='queued' and new.status='dispatched' and old.request_count=0 and new.request_count=1 or old.status='queued' and new.status='cancelled' and new.request_count=0 or old.status='dispatched' and new.status in('completed','failed','billing_uncertain') and new.request_count=1 and new.worker_id=old.worker_id and new.dispatched_at=old.dispatched_at) then raise exception 'NATIVE48_NO_RETRY_OR_MUTATION';end if;
 end if;return new;end $$;
create trigger native48_run_state before update or delete on public.analysis_luna_native48_runs for each row execute function public.native48_state_guard();
create trigger native48_task_state before update or delete on public.analysis_luna_native48_tasks for each row execute function public.native48_state_guard();
create function public.native48_save_plan(p_actor text,p_user uuid,p_manifest jsonb,p_sha text) returns uuid language plpgsql security invoker set search_path='' as $$
declare source jsonb;s public.analysis_luna_balanced_sets;pid uuid;it jsonb;c public.analysis_luna_balanced_cases;input jsonb;begin
 source=public.native48_source_check();select * into s from public.analysis_luna_balanced_sets where id=(source->'set'->>'id')::uuid;
 if current_user<>'service_role' or not(p_actor='codex_admin' and p_user is null or p_actor='app_user' and p_user is not null and exists(select 1 from public.organization_members where organization_id=s.organization_id and user_id=p_user and role in('owner','admin','manager'))) then raise exception 'FORBIDDEN';end if;
 if p_manifest->>'version' is distinct from 'luna-native-balanced48-run-v1' or p_manifest->>'set_id' is distinct from s.id::text or p_manifest->>'seal_id' is distinct from '24883941-e3bc-4759-9af6-d21bd62413f9' or p_manifest->>'organization_id' is distinct from s.organization_id::text or p_manifest->>'dataset_sha256' is distinct from s.manifest_sha256 or p_manifest->>'reference_sha256' is distinct from 'ba06732a224c7f34b68208551abcc88d5d6c42b9713c32663d44df3e37df7781' or p_manifest->>'config_sha256' is distinct from '36c76407430d1f88c862db5a0d7dbb223f4a38d91d6481f3897f2ddd0c6d4c44' or p_manifest->>'config_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(p_manifest->'config'),'sha256'),'hex') or p_manifest->>'configuration_id' is distinct from 'luna-native-balanced48-choice-v1' or p_manifest->>'model' is distinct from 'gpt-6-luna' or p_manifest->>'endpoint' is distinct from '/v1/decisions' or p_manifest->>'max_calls' is distinct from '48' or p_manifest->>'repeat_count' is distinct from '1' or p_manifest->>'automatic_retry' is distinct from 'false' or p_manifest->>'production_enabled' is distinct from 'false' or p_manifest->>'original_language_text' is distinct from 'true' or p_manifest->>'input_rate_per_million' is distinct from '0.1' or p_sha is distinct from encode(extensions.digest(public.jev_economy_canonical(p_manifest),'sha256'),'hex') or jsonb_array_length(p_manifest->'cases')<>48 or (select count(distinct q->>'review_id') from jsonb_array_elements(p_manifest->'cases') q)<>48 or (select count(distinct q->>'position') from jsonb_array_elements(p_manifest->'cases') q)<>48 then raise exception 'NATIVE48_PLAN_INVALID';end if;
 if (p_manifest->>'estimated_input_tokens')::numeric<>(select sum((q->'estimate'->>'estimated_input_tokens')::numeric) from jsonb_array_elements(p_manifest->'cases') q) or (p_manifest->>'estimated_cost_usd')::numeric<>(p_manifest->>'estimated_input_tokens')::numeric*0.1/1000000 then raise exception 'NATIVE48_COST_CHANGED';end if;
 for it in select value from jsonb_array_elements(p_manifest->'cases') loop
  select * into c from public.analysis_luna_balanced_cases where set_id=s.id and review_id=(it->>'review_id')::uuid;input=(it->'payload'->>'input')::jsonb;
  if c.review_id is null or it->>'position' is distinct from c.position::text or it->>'theme_key' is distinct from c.theme_key or it->>'polarity' is distinct from c.proposed_polarity or it->>'source_text_sha256' is distinct from c.original_text_sha256 or it->>'candidate_sha256' is distinct from c.candidate_sha256 or it->>'request_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(it->'payload'),'sha256'),'hex') or it->'payload'->>'model' is distinct from 'gpt-6-luna' or jsonb_array_length(it->'payload'->'questions')<>1 or it->'payload'->'questions'->0->>'type' is distinct from 'choice' or input->>'original_review_text' is distinct from c.original_text or input->>'review_alias' is distinct from 'native48_'||c.position::text or (select count(*) from jsonb_object_keys(input))<>2 then raise exception 'NATIVE48_CASE_CHANGED';end if;
 end loop;
 perform pg_advisory_xact_lock(hashtextextended(s.id::text||':native48-plan',0));select id into pid from public.analysis_luna_native48_plans where set_id=s.id and seal_id='24883941-e3bc-4759-9af6-d21bd62413f9';if found then if not exists(select 1 from public.analysis_luna_native48_plans where id=pid and manifest_sha256=p_sha) then raise exception 'NATIVE48_PLAN_CHANGED';end if;return pid;end if;
 insert into public.analysis_luna_native48_plans(organization_id,set_id,seal_id,version,manifest,manifest_sha256,created_by,actor_kind) values(s.organization_id,s.id,(p_manifest->>'seal_id')::uuid,p_manifest->>'version',p_manifest,p_sha,p_user,p_actor) returning id into pid;return pid;
end $$;
create function public.native48_task_insert_guard() returns trigger language plpgsql security invoker set search_path='' as $$declare it jsonb;begin
 select value into it from public.analysis_luna_native48_runs r join public.analysis_luna_native48_plans p on p.id=r.plan_id cross join lateral jsonb_array_elements(p.manifest->'cases') where r.id=new.run_id and r.organization_id=new.organization_id and r.status='queued' and value->>'position'=new.position::text;
 if it is null or new.status<>'queued' or new.request_count<>0 or it->>'review_id' is distinct from new.review_id::text or it->>'theme_key' is distinct from new.theme_key or it->>'polarity' is distinct from new.polarity or it->'payload' is distinct from new.payload or it->>'request_sha256' is distinct from new.request_sha256 or it->>'source_text_sha256' is distinct from new.source_text_sha256 then raise exception 'NATIVE48_TASK_OUT_OF_SCOPE';end if;return new;end $$;
create trigger native48_task_insert before insert on public.analysis_luna_native48_tasks for each row execute function public.native48_task_insert_guard();
create function public.native48_authorize_delegated(p_plan uuid,p_sha text,p_cost numeric,p_authorization jsonb) returns uuid language plpgsql security invoker set search_path='' as $$
declare p public.analysis_luna_native48_plans;rid uuid;it jsonb;scope jsonb;begin
 if current_user<>'service_role' then raise exception 'FORBIDDEN';end if;perform public.native48_source_check();select * into p from public.analysis_luna_native48_plans where id=p_plan;scope=p_authorization->'scope';
 if p.id is null or p_sha is distinct from p.manifest_sha256 or p_cost is distinct from (p.manifest->>'estimated_cost_usd')::numeric or p_authorization->>'consent_source' is distinct from 'user_directive_codex_delegation' or p_authorization->>'authorization_commit_sha' is distinct from '1b36499e81197d4ac0edc8cb9b7e6afa877214af' or p_authorization->>'authorization_spec_sha256' is distinct from 'a2c5ca649169884194cacbdc345b9faa70f82c4deb8d73a8e8e7ed2729f48386' or p_authorization->'operator_identity' is distinct from '{"kind":"codex_admin","channel":"supabase_mcp"}'::jsonb or scope is distinct from jsonb_build_object('set_id',p.set_id,'seal_id',p.seal_id,'protocol_version','luna-native-balanced48-run-v1','model','gpt-6-luna','endpoint','/v1/decisions','max_calls',48,'attempts_per_case',1,'automatic_retry',false) then raise exception 'NATIVE48_DELEGATION_CHANGED';end if;
 perform pg_advisory_xact_lock(hashtextextended(p.set_id::text||':native48-consent',0));select id into rid from public.analysis_luna_native48_runs where plan_id=p.id;if found then return rid;end if;
 insert into public.analysis_luna_native48_runs(plan_id,organization_id,consent_source,operator_identity,authorization_commit_sha,authorization_spec_sha256,authorization_record,authorization_sha256,authorization_recorded_by_role,manifest_sha256,estimated_cost_usd) values(p.id,p.organization_id,'user_directive_codex_delegation',p_authorization->'operator_identity',p_authorization->>'authorization_commit_sha',p_authorization->>'authorization_spec_sha256',p_authorization,encode(extensions.digest(public.jev_economy_canonical(p_authorization),'sha256'),'hex'),current_user,p_sha,p_cost) returning id into rid;
 for it in select value from jsonb_array_elements(p.manifest->'cases') loop insert into public.analysis_luna_native48_tasks(run_id,organization_id,position,review_id,theme_key,polarity,payload,request_sha256,source_text_sha256) values(rid,p.organization_id,(it->>'position')::int,(it->>'review_id')::uuid,it->>'theme_key',it->>'polarity',it->'payload',it->>'request_sha256',it->>'source_text_sha256');end loop;
 insert into public.analysis_luna_native48_events(run_id,organization_id,event,body) values(rid,p.organization_id,'user_directive_codex_delegation',jsonb_build_object('scope',scope,'authorization_commit_sha',p_authorization->>'authorization_commit_sha','operator_identity',p_authorization->'operator_identity','estimated_cost_usd',p_cost,'manifest_sha256',p_sha));return rid;
end $$;
create function public.native48_claim(p_worker uuid,p_run uuid) returns jsonb language plpgsql security invoker set search_path='' as $$declare t public.analysis_luna_native48_tasks;r public.analysis_luna_native48_runs;begin
 select * into r from public.analysis_luna_native48_runs where id=p_run and status in('queued','running') for update;if r.id is null then return null;end if;perform public.native48_source_check();
 if r.consent_source<>'user_directive_codex_delegation' or r.authorization_sha256<>encode(extensions.digest(public.jev_economy_canonical(r.authorization_record),'sha256'),'hex') then raise exception 'NATIVE48_DELEGATION_CHANGED';end if;
 update public.analysis_luna_native48_tasks set status='billing_uncertain',completed_at=now(),error_code='WORKER_RESPONSE_LOST' where run_id=r.id and status='dispatched' and dispatched_at<now()-interval '5 minutes';
 select * into t from public.analysis_luna_native48_tasks where run_id=r.id and status='queued' order by position for update skip locked limit 1;if t.id is null then return null;end if;if (select coalesce(sum(request_count),0) from public.analysis_luna_native48_tasks where run_id=r.id)>=48 then return null;end if;
 if r.status='queued' then update public.analysis_luna_native48_runs set status='running' where id=r.id;end if;update public.analysis_luna_native48_tasks set status='dispatched',request_count=1,worker_id=p_worker,dispatched_at=now() where id=t.id returning * into t;insert into public.analysis_luna_native48_events(run_id,organization_id,event,body) values(r.id,r.organization_id,'attempt_reserved',jsonb_build_object('task_id',t.id,'position',t.position));return to_jsonb(t);
end $$;
create function public.native48_finish(p_task uuid,p_worker uuid,p_status text,p_output jsonb) returns boolean language plpgsql security invoker set search_path='' as $$declare t public.analysis_luna_native48_tasks;begin
 select * into t from public.analysis_luna_native48_tasks where id=p_task for update;if t.id is null or t.worker_id is distinct from p_worker or t.status<>'dispatched' or p_status not in('completed','failed','billing_uncertain') then return false;end if;
 if p_output->'response' is not null and p_output->>'response_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(p_output->'response'),'sha256'),'hex') then raise exception 'NATIVE48_RESPONSE_CHANGED';end if;
 update public.analysis_luna_native48_tasks set status=p_status,completed_at=now(),response=p_output->'response',response_sha256=p_output->>'response_sha256',parsed=p_output->'parsed',served_model=p_output->>'served_model',answer_type=p_output->>'answer_type',response_id=p_output->>'response_id',provider_request_id=p_output->>'provider_request_id',input_tokens=(p_output->>'input_tokens')::bigint,output_tokens=(p_output->>'output_tokens')::bigint,usage_details=p_output->'usage_details',cost_usd=(p_output->>'cost_usd')::numeric,duration_ms=(p_output->>'duration_ms')::bigint,error_code=p_output->>'error_code' where id=t.id;insert into public.analysis_luna_native48_events(run_id,organization_id,event,body) values(t.run_id,t.organization_id,p_status,jsonb_build_object('task_id',t.id,'error_code',p_output->>'error_code'));return true;
end $$;
create function public.native48_complete(p_run uuid,p_result jsonb,p_sha text) returns boolean language plpgsql security invoker set search_path='' as $$declare r public.analysis_luna_native48_runs;state text;begin
 select * into r from public.analysis_luna_native48_runs where id=p_run for update;if r.id is null or r.status not in('queued','running') or exists(select 1 from public.analysis_luna_native48_tasks where run_id=r.id and status in('queued','dispatched')) then return false;end if;
 if (select count(*) from public.analysis_luna_native48_tasks where run_id=r.id)<>48 or p_result->>'version' is distinct from 'luna-native-balanced48-run-v1' or p_result->>'independent_human_validation' is distinct from 'false' or p_result->>'config_sha256' is distinct from '36c76407430d1f88c862db5a0d7dbb223f4a38d91d6481f3897f2ddd0c6d4c44' or (p_result->>'attempts')::int<>(select sum(request_count) from public.analysis_luna_native48_tasks where run_id=r.id) or p_sha is distinct from encode(extensions.digest(public.jev_economy_canonical(p_result),'sha256'),'hex') then raise exception 'NATIVE48_RESULT_INVALID';end if;
 state=case when exists(select 1 from public.analysis_luna_native48_tasks where run_id=r.id and status='billing_uncertain') then 'billing_uncertain' when exists(select 1 from public.analysis_luna_native48_tasks where run_id=r.id and status in('failed','cancelled')) then 'failed' else 'completed' end;
 insert into public.analysis_luna_native48_results(run_id,organization_id,body,result_sha256) values(r.id,r.organization_id,p_result,p_sha);update public.analysis_luna_native48_runs set status=state,result=p_result,result_sha256=p_sha,completed_at=now() where id=r.id;insert into public.analysis_luna_native48_events(run_id,organization_id,event,body) values(r.id,r.organization_id,'execution_terminal',jsonb_build_object('status',state,'result_sha256',p_sha));return true;
end $$;
create function public.native48_stop_unsent(p_run uuid,p_error text) returns void language plpgsql security invoker set search_path='' as $$begin update public.analysis_luna_native48_runs set status='running' where id=p_run and status='queued';update public.analysis_luna_native48_tasks set status='cancelled',completed_at=now(),error_code=p_error where run_id=p_run and status='queued';end $$;
create function public.native48_wake(p_run uuid) returns bigint language plpgsql security invoker set search_path='' as $$declare r public.analysis_luna_native48_runs;request bigint;begin
 select * into r from public.analysis_luna_native48_runs where id=p_run and status in('queued','running');if r.id is null then return null;end if;if r.consent_source<>'user_directive_codex_delegation' then raise exception 'NATIVE48_DELEGATION_REQUIRED';end if;
 select net.http_post(url:='https://ihuztjkblywzjdruusdj.supabase.co/functions/v1/process-luna-native48',headers:=jsonb_build_object('Content-Type','application/json','x-home-reviews-scheduler',(select decrypted_secret from vault.decrypted_secrets where name='home_reviews_scheduler_token')),body:='{}'::jsonb,timeout_milliseconds:=180000) into request;insert into public.analysis_luna_native48_events(run_id,organization_id,event,body) values(r.id,r.organization_id,'authorized_worker_wake',jsonb_build_object('database_role',current_user,'request_id',request));return request;
end $$;
create function public.native48_economic_context() returns jsonb language sql security invoker set search_path='' as $$
 select jsonb_build_object('artisan',(select jsonb_build_object('calls',sum(request_count),'input_tokens',sum(input_tokens),'output_tokens',sum(output_tokens),'known_cost_usd',sum(cost_usd),'unknown_cost_calls',count(*) filter(where request_count=1 and cost_usd is null),'average_text_characters',avg(char_length((payload->>'input')::jsonb->>'analysis_text')),'language','English analytical text','questions_per_call',1) from public.analysis_decisions_evidence40_tasks where organization_id='93228bbb-6397-41e3-b8be-21ee7060eda7'),'multirest_english',(select jsonb_build_object('calls',sum(request_count),'input_tokens',sum(input_tokens),'output_tokens',sum(output_tokens),'known_cost_usd',sum(cost_usd),'unknown_cost_calls',count(*) filter(where request_count=1 and cost_usd is null),'average_text_characters',avg(char_length((payload->>'input')::jsonb->>'analysis_text')),'language','English analytical text','questions_per_call',1) from public.analysis_luna_multirest_tasks where organization_id='93228bbb-6397-41e3-b8be-21ee7060eda7'),'paired_accuracy_comparison',false);
$$;
do $$declare fn text;begin foreach fn in array array['native48_source_check()','native48_state_guard()','native48_task_insert_guard()','native48_save_plan(text,uuid,jsonb,text)','native48_authorize_delegated(uuid,text,numeric,jsonb)','native48_claim(uuid,uuid)','native48_finish(uuid,uuid,text,jsonb)','native48_complete(uuid,jsonb,text)','native48_stop_unsent(uuid,text)','native48_wake(uuid)','native48_economic_context()'] loop execute 'revoke all on function public.'||fn||' from public,anon,authenticated';execute 'grant execute on function public.'||fn||' to service_role';end loop;end $$;
-- Scheduling an empty queue cannot create consent or spend. Only an explicit delegated authorization_record adds work.
select cron.schedule('home-reviews-luna-native48-v1','* * * * *',$cron$select public.native48_wake(id) from public.analysis_luna_native48_runs where status in('queued','running')$cron$);
